import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 32 · Christmas recipe: shortbread (Google Trends 3/11: shortbread rising topic in christmas recipes)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, the best Christmas cookie I ever ate had only three ingredients. Butter, sugar and flour. That's all. It came in a round tin with a Scottish soldier on the lid, and Mrs. MacLeod next door made it every December from her mother's recipe from Glasgow. One bite, and it melted on my tongue like snow.""",
   "shortbread cookies Christmas tin", "ONLY THREE INGREDIENTS")
sc("""But when people make shortbread at home, it comes out hard as a brick, or so crumbly it falls apart before it reaches your mouth. So tonight I'm giving you Mrs. MacLeod's shortbread, every step, and the four mistakes that ruin it. And stay with me, because mistake number four is the one that even good bakers make, and it happens before you turn on the oven.""",
   "crumbly broken shortbread plate", "HARD OR CRUMBLY")

ch("Mrs. MacLeod's tin")
sc("""Mrs. MacLeod came to Mansfield from Scotland in nineteen twenty-three, married to a man who worked at the steel mill. She had a voice like a song, and she called every child on the street hen. Come here, hen, try this. And every Christmas Eve, she walked down the street with a basket of tins, one for every house, wrapped in a red plaid ribbon.""",
   "elderly Scottish woman basket Christmas", "COME HERE, HEN")
sc("""In Scotland, she told me, shortbread was for Hogmanay, the New Year, more than Christmas. You gave it to the first person who walked through your door after midnight, for luck. She kept that tradition her whole life in Ohio. If you knocked on her door after midnight on New Year's, you went home with shortbread, whether you liked it or not.""",
   "New Year's Eve door knocking night", "SHORTBREAD FOR LUCK")
sc("""When I was fourteen, I asked her for the recipe, and she laughed and said, hen, there's no recipe. One part sugar, two parts butter, three parts flour. That's all anybody needs to know. And she was right. One, two, three. It's the easiest recipe in the world to remember. And in a minute I'll tell you the secret ingredient she didn't mention, because it isn't really an ingredient.""",
   "teenage girl old woman kitchen 1950s", "ONE, TWO, THREE")

ch("What you need")
sc("""Here's what you need, honey. One cup of good butter, that's two sticks, softened. Half a cup of sugar. Mrs. MacLeod used plain white sugar, but I like powdered sugar, because it makes them melt even more. Two cups of all-purpose flour. And a quarter teaspoon of salt, if your butter is unsalted. That's the whole list.""",
   "butter sugar flour bowls", "THE WHOLE LIST")
sc("""Now, the butter. With only three ingredients, the butter is everything. Buy the best butter you can afford. The European-style butters, with a little more fat, make the most tender shortbread you've ever tasted. Mrs. MacLeod said, if you use cheap butter, you're making cheap shortbread, and I won't have it in my tins.""",
   "block of butter close up", "THE BUTTER IS EVERYTHING")
sc("""And one more thing, a trick for a more tender cookie. Replace a quarter cup of the flour with a quarter cup of cornstarch, or rice flour if you can find it. It makes the shortbread sandier and more delicate. Mrs. MacLeod used rice flour, and it was the reason hers crumbled just right in your mouth, but not in your hand.""",
   "cornstarch rice flour measuring", "SANDY, NOT CRUMBLY")

ch("Step by step")
sc("""Step one. Beat the soft butter with the sugar until it's smooth and creamy, about two minutes. Not fluffy, just smooth. Then add the flour and salt, and mix it slowly, only until it comes together into a soft dough. Stop the minute you can't see dry flour. It will look a little crumbly. Press it together with your hands.""",
   "mixing shortbread dough bowl", "STOP AT DRY FLOUR")
sc("""And this is mistake number one, the one that makes shortbread hard as a brick. Overmixing. The more you work flour, the tougher it gets. Shortbread should be handled as little as possible. Mrs. MacLeod mixed hers with her fingertips in about one minute, and she said, gentle hands, hen. Gentle hands make tender shortbread.""",
   "hands pressing dough gently", "GENTLE HANDS")
sc("""If this is helping you, honey, tap the like button for me. It helps Grandma more than you know. Now, step two. Press the dough into an eight or nine inch round cake pan, or a square pan, in an even layer about half an inch thick. Smooth the top with the bottom of a glass. Then prick it all over with a fork, in neat rows.""",
   "pressing dough round pan fork", "PRICK IT ALL OVER")
sc("""Why the fork, sweetheart? So the steam can escape while it bakes, and the shortbread stays flat and doesn't puff or bubble. And it makes that pretty pattern you see on the tins. Then, with a knife, score it lightly into wedges, like a pie, or into fingers, before it goes in the oven. It will break cleanly along those lines later.""",
   "shortbread round scored wedges", "SCORE IT FIRST")
sc("""Step three, and here's the secret ingredient I promised you. Time in the cold. Put the pan in the icebox for thirty minutes before baking. Cold butter holds the shape, and the shortbread bakes evenly without spreading at the edges. Mrs. MacLeod didn't call it an ingredient. She just said, let it rest, the way you rest after supper.""",
   "pan refrigerator chilling dough", "LET IT REST")
sc("""Step four. Bake at three hundred twenty-five degrees, low, for about thirty to thirty-five minutes. And here's mistake number two. Too hot an oven. Shortbread should be pale, the color of sand, with just the faintest gold at the edges. If it browns, it turns hard and bitter. Low and slow, and pale.""",
   "pale golden shortbread oven", "THE COLOR OF SAND")
sc("""How do you know it's done, honey? Don't go by the clock alone. Look at the edges. They should be just barely golden, the color of straw, while the middle is still pale. Press the center lightly with your finger. It should feel set, not soft and squishy. Every oven is different. Mine runs hot, so I check at twenty-eight minutes, every single time.""",
   "checking shortbread edges oven", "THE COLOR OF STRAW")
sc("""Step five. As soon as it comes out, while it's still warm and soft, cut along your scored lines again with a sharp knife, and sprinkle it with a little sugar. Then leave it in the pan to cool completely, at least an hour. Mistake number three is taking it out too soon. Warm shortbread falls apart. Cool shortbread snaps clean.""",
   "cutting warm shortbread pan", "COOL SHORTBREAD SNAPS CLEAN")

ch("The fourth mistake")
sc("""So far, gentle hands, the fork, the rest in the cold, a low oven, and cooling in the pan. Now the fourth mistake, the one I told you about at the start, the one that happens before you turn on the oven. Butter that's too soft, or melted. If the butter is greasy and shiny, your shortbread will be greasy and flat, no matter what you do after.""",
   "melted butter greasy bowl", "TOO SOFT")
sc("""Soft butter should hold the dent of your finger, but not be shiny or oily. Leave it on the counter for about an hour, not in the microwave. If you forgot, cut it into small cubes and it will soften in twenty minutes. Mrs. MacLeod kept her butter in a covered dish on the windowsill all winter. Ohio kitchens were cold enough.""",
   "butter dish windowsill winter", "THE DENT OF YOUR FINGER")

sc("""And if your shortbread does come out hard, don't throw it away. Crumble it over vanilla ice cream, or use it instead of graham crackers for a pie crust, or layer it with whipped cream and berries in a glass. Mrs. MacLeod said, there's no such thing as ruined shortbread, hen. Just shortbread that wants to be something else.""",
   "crumbled shortbread ice cream dessert", "SOMETHING ELSE")

ch("Christmas variations")
sc("""Now, for Christmas, you can dress it up. Dip one end of each finger in melted chocolate and let it set on wax paper. Or mix in a handful of chopped dried cranberries and a spoon of orange zest. Or add a teaspoon of chopped fresh rosemary. That sounds strange, honey, but it's the one my grown grandchildren ask for every year.""",
   "chocolate dipped shortbread cranberry", "ROSEMARY SHORTBREAD")
sc("""Or make little shortbread cutouts. Roll the chilled dough between two sheets of parchment, a quarter inch thick, cut stars and trees, and bake them for fifteen to eighteen minutes. They hold their shape perfectly, because there's no egg and no baking powder to make them spread. Shortbread is the best dough there is for cookie cutters.""",
   "shortbread star cookies cutter", "THEY HOLD THEIR SHAPE")

ch("Keeping and giving")
sc("""Shortbread keeps longer than any cookie I know. Two weeks in a tin at room temperature, and it actually gets better after a few days, as the butter flavor settles in. It mails beautifully, packed tight in a tin with wax paper. And it freezes for three months, baked or as dough. I bake mine the first week of December and forget about it until I need it.""",
   "shortbread tin wax paper", "IT GETS BETTER")
sc("""And do what Mrs. MacLeod did. A round of shortbread in a tin, tied with plaid ribbon, for every house on your street. It costs about two dollars a tin. When she passed in nineteen seventy-four, at ninety-one, every family on Elm Street came to the funeral, and the minister said she had fed the whole street for fifty years, one tin at a time.""",
   "tins tied plaid ribbon Christmas", "ONE TIN AT A TIME")

ch("Grandma's kitchen")
sc("""So one more time, honey. One, two, three. One part sugar, two parts good butter, three parts flour, and a little cornstarch for tenderness. Soft butter, not melted. Gentle hands. Prick it, score it, chill it. Three twenty-five, pale as sand. Cut it warm and cool it in the pan. That's Mrs. MacLeod's shortbread, and it has never once been a brick.""",
   "shortbread wedges plate Christmas", "NEVER A BRICK")
sc("""Tell me in the comments, sweetheart. Did somebody on your street bring cookies at Christmas? I'd love to hear about them. The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, hen. Merry Christmas.""",
   "Christmas street houses snow evening", "WHO BROUGHT YOU COOKIES?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma32", "Christmas Shortbread That NEVER Crumbles (Only 3 Ingredients)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Traditional Scottish shortbread ratio of 1 part sugar, 2 parts butter, 3 parts flour; shortbread and first-footing at Hogmanay.",
      "Recipe as written by Grandma Ruth: 1 cup butter, 1/2 cup sugar or powdered sugar, 1 3/4 cups flour plus 1/4 cup cornstarch or rice flour, 1/4 tsp salt; chill 30 minutes; 325 F for 30 to 35 minutes."],
     "christmas recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
